SELECT JSON_OBJECT('row',JSON_OBJECT(CONVERT(X'636f756e7473' USING utf8mb4),JSON_OBJECT(CONVERT(X'513035' USING utf8mb4),COALESCE(SUM(CASE WHEN 1=1 THEN 1 ELSE 0 END),0),CONVERT(X'513036' USING utf8mb4),COALESCE(SUM(CASE WHEN a.province IN (CONVERT(X'e5b9bfe4b89ce79c81' USING utf8mb4),CONVERT(X'e5b9bfe4b89c' USING utf8mb4)) THEN 1 ELSE 0 END),0),CONVERT(X'513037' USING utf8mb4),COALESCE(SUM(CASE WHEN a.province IN (CONVERT(X'e5b9bfe4b89ce79c81' USING utf8mb4),CONVERT(X'e5b9bfe4b89c' USING utf8mb4)) AND a.city IN (CONVERT(X'e5b9bfe5b79ee5b882' USING utf8mb4),CONVERT(X'e5b9bfe5b79e' USING utf8mb4)) AND p.education IN (CONVERT(X'44415a4855414e' USING utf8mb4),CONVERT(X'47414f5a4849' USING utf8mb4)) THEN 1 ELSE 0 END),0),CONVERT(X'513038' USING utf8mb4),COALESCE(SUM(CASE WHEN a.province IN (CONVERT(X'e5b9bfe4b89ce79c81' USING utf8mb4),CONVERT(X'e5b9bfe4b89c' USING utf8mb4)) AND a.city IN (CONVERT(X'e6b7b1e59cb3e5b882' USING utf8mb4),CONVERT(X'e6b7b1e59cb3' USING utf8mb4)) AND p.experience IN (CONVERT(X'47524144554154494e47' USING utf8mb4),CONVERT(X'4f4e5f43414d505553' USING utf8mb4)) THEN 1 ELSE 0 END),0)))) FROM (SELECT DISTINCT pc.position_id FROM c_position_chain pc WHERE pc.deleted=0 AND pc.industry_chain_id IN (15,295,357,407,15396,15397,15398,15399,15400,15401,15402,15403,15404,15405,15406,15407,15408,15409,15410,15411,15412,15413,15414,15415,15416,15417,15418,15419,15420,15421,15422,15423,15424,15425,15426,15427,15428,15429,15430,15431,15432,15433,15434,15435,15436,15437,15438,15439,15440,15441,15442,15443,15444,15445,15446,15447,15448,15449,15450,15451,15452,15453,15454,15455,15456,15457,15458,15459,15460,15461,15462,15463,15464,15465,15466,15467,15468,15469,15470,15471,15472,15473,15474,15475,15476,15477,15478,15479,15480,15481,15482,15483,15484,15485,15486,15487,15488,15489,15490,15491,15492,15493,15494,15495,15496,15497,15498,15499,15500,15501,15502,15503,15504,15505,15506,15507,15508,15509,15510,15511)) industry_candidates JOIN c_company_position p ON p.id=i